item.command:
/bin/zsh -lc "printf '%s\\n' '### locked Profile'
sed -n '1,9999p' .planning/milestones/M003/reviews/evidence/start/locked-profile.yaml
printf '%s\\n' '### pointer headers'
for f in .planning/milestones/M003/product/overview.md .planning/milestones/M003/product/data-assets.md .planning/milestones/M003/product/abilities.md .planning/milestones/M003/product/pages/index.md .planning/milestones/M003/product/ai-behavior.md; do printf '\\n%s\\n' \""'$f"; rg -n -m 4 '"'M003-PRODUCT-11|pronunciation/' \""'$f"; done
printf '"'%s\\n' '### hash manifest comparison'
node - <<'NODE'
const fs=require('fs'),crypto=require('crypto');
const m=JSON.parse(fs.readFileSync('.planning/milestones/M003/reviews/evidence/pronunciation-design-entry-107/product-manifest.json','utf8'));
let bad=[];
for(const [p,want] of Object.entries(m.files)){const got=crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex'); if(got"'!==want)bad.push({p,want,got});}
console.log(JSON.stringify({checked:Object.keys(m.files).length,matched:Object.keys(m.files).length-bad.length,mismatches:bad},null,2));
NODE
printf '"'%s\\n' '### registered name validation'
../agt-coding-v2/validators/validate-agent-name.sh designer-tony; printf 'exit=%s\\n' \""'$?"
printf '"'%s\\n' '### designated technical open items'
rg -n -C 1 'OPEN-40[123]|designer-tony|prototype|formal|M002/M003|UAT3015|4174' .planning/milestones/M003/product/pronunciation .planning/milestones/M003/handoffs/product.md"

